ruleToc.chapterList:
-@js:
eval(String(source.bookSourceComment));
aList=org.jsoup.Jsoup.parse(result).select('.chapter-item a')
list=[]
for(i in aList){list[i]={"title":String(aList[i].text()),"curl":aList[i].attr('href')}}

if(/大人，更多话在这里/.test(java.getString("@@.show-more@text"))){
 id=baseUrl.match(/\d+(?=\/)/g)[0]
 url=v+"/bookchapter/"
 by=java.post(url,"id="+id+"&id2=1",{}).body()
 //java.log(id)
 JSON.parse(by).forEach(i=>list.push({"title":i.name,"curl":`/${id}/${i.id}.html`}))
}

list
